#!/usr/bin/env node

const { spawn } = require("child_process");
const { existsSync } = require("fs");
const path = require("path");
const { getInstallDir, main: install } = require("./install.js");

const ext = process.platform === "win32" ? ".exe" : "";

// The postinstall copy, then the persistent one install.js also writes.
function findBinary() {
  const candidates = [
    path.join(__dirname, "bin", `belt${ext}`),
    path.join(getInstallDir(), `belt${ext}`),
  ];
  return candidates.find((p) => existsSync(p));
}

function run(bin) {
  const child = spawn(bin, process.argv.slice(2), { stdio: "inherit" });
  child.on("error", (err) => {
    console.error(err.message);
    process.exit(1);
  });
  child.on("exit", (code) => process.exit(code ?? 1));
}

async function start() {
  let bin = findBinary();
  if (!bin) {
    // postinstall did not run (--ignore-scripts) or failed: install now.
    // Its progress goes to stderr so stdout stays clean for the command.
    const log = console.log;
    console.log = console.error;
    try {
      await install();
    } catch (err) {
      console.error(
        "belt binary not found and could not be downloaded: " + err.message + "\n" +
        "install directly instead:\n" +
        "  macOS / Linux / Git Bash:  curl -fsSL https://cli.inference.sh | sh\n" +
        "  Windows PowerShell:        irm https://cli.inference.sh/install.ps1 | iex"
      );
      process.exit(1);
    } finally {
      console.log = log;
    }
    bin = findBinary();
  }
  run(bin);
}

start();
